#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
Paper Trading Skill Module - A-Share Paper Trading with Strategy Engine and Backtesting
===========================================
"""

import os
import json
import logging
from datetime import datetime, date, timedelta
from typing import Dict, List, Optional, Tuple, Any
from dataclasses import dataclass, field
from pathlib import Path
import pandas as pd
import numpy as np

logging.basicConfig(level=logging.INFO, format='[%(asctime)s] [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)


@dataclass
class TradingFees:
    commission_rate: float = 0.00025
    commission_min_amount: float = 5.0
    stamp_tax_rate: float = 0.001
    transfer_fee_rate: float = 0.00002
    last_updated: str = "2024-09-01"

    def calculate_trade_cost(self, trade_amount: float, direction: str) -> Dict[str, float]:
        commission = trade_amount * self.commission_rate
        if commission < self.commission_min_amount:
            commission = self.commission_min_amount

        stamp_tax = trade_amount * self.stamp_tax_rate if direction == 'sell' else 0.0
        transfer_fee = trade_amount * self.transfer_fee_rate

        total_cost = round(commission + stamp_tax + transfer_fee, 2)
        return {
            'commission': round(commission, 2),
            'stamp_tax': round(stamp_tax, 2),
            'transfer_fee': round(transfer_fee, 2),
            'total_cost': total_cost,
            'trade_amount': trade_amount
        }


class BoardType:
    def __init__(self):
        self.main_board = 0.10
        self.chinext = 0.20
        self.star_market = 0.20
        self.st_stock = 0.05

    @classmethod
    def get_limit(cls, board: str) -> float:
        limits = {
            'main_board': 0.10,
            'chinext': 0.20,
            'star_market': 0.20,
            'st_stock': 0.05
        }
        return limits.get(board, 0.10)


class TradeType:
    BUY = 'buy'
    SELL = 'sell'


@dataclass
class Trade:
    trade_id: str
    date: str
    stock_code: str
    board: str
    direction: str
    price: float
    quantity: int
    trade_amount: float
    costs: Dict[str, float] = field(default_factory=dict)
    pnl: float = 0.0
    pnl_rate: float = 0.0
    stop_loss_hit: bool = False
    stop_loss_reason: str = ""

    def __str__(self):
        return f"{self.direction} {self.stock_code} {self.quantity} shares @ ¥{self.price:.2f}"


class PaperTradingEngine:
    """A-Share paper trading engine with T+1 settlement and proper fee calculation."""

    def __init__(self, initial_capital: float = 1000000.0):
        self.initial_capital = initial_capital
        self.cash = initial_capital
        self.position = {}
        self.t_plus_one_shares = {}
        self.t_plus_one_funds = []
        self.portfolio_value_history = []
        self.trade_history = []
        self.calculated_fees = TradingFees()
        self.market_holidays = set()
        self.current_date = None
        self.stock_list = {}
        self.historical_data = {}

    def load_market_holidays(self, holiday_file: str = None):
        if holiday_file:
            try:
                df = pd.read_csv(holiday_file)
                self.market_holidays = set(df['date'].astype(str).tolist())
            except Exception as e:
                logger.warning(f"Failed to load holidays: {e}")

    def load_stock_list(self, stock_list_file: str = None):
        if stock_list_file:
            try:
                df = pd.read_csv(stock_list_file)
                self.stock_list = {}
                for _, row in df.iterrows():
                    code = str(row['code'])
                    self.stock_list[code] = {
                        'name': row['name'],
                        'board': row['board'],
                        'lot_size': int(row['lot_size']),
                        'price_limit': float(row['price_limit'])
                    }
            except Exception as e:
                logger.warning(f"Failed to load stock list: {e}")

    def is_trading_day(self, date: date) -> bool:
        return date not in self.market_holidays

    def get_market_open(self) -> bool:
        if not self.is_trading_day(self.current_date):
            return False

        h = self.current_date.hour
        m = self.current_date.minute

        if (9 <= h < 11 and m <= 30) or (h == 13 and 0 <= m <= 30):
            return True
        if h == 9 and 15 <= m <= 25:
            return True
        if h == 14 and (57 <= m <= 60):
            return True
        if h == 15 and m == 0:
            return True
        return False

    def get_board(self, stock_code: str) -> str:
        """Determine board type from stock code."""
        if not stock_code:
            return 'main_board'

        code = str(stock_code)[:3]
        if code.startswith('sh600') or code.startswith('sh601') or code.startswith('sh603'):
            return 'main_board'
        elif code.startswith('sz000') or code.startswith('sz001'):
            return 'main_board'
        elif code.startswith('sz300') or code.startswith('sz301'):
            return 'chinext'
        elif code.startswith('sh688'):
            return 'star_market'
        return 'main_board'

    def validate_price(self, price: float, date: date, stock_code: str) -> Tuple[bool, float, str]:
        """Validate price against board's price limits."""
        if not self.is_trading_day(date):
            return False, None, "Non-trading day"

        if date not in self.historical_data:
            return True, price, "No historical data"

        today_df = self.historical_data[date]
        if stock_code in today_df['code'].values:
            today_close = today_df[today_df['code'] == stock_code]['close'].iloc[-1]
        else:
            return True, price, "No price data for stock"

        board = self.get_board(stock_code)
        limit_pct = self.board_limits.get(board, 0.10)
        limit_up = today_close * (1 + limit_pct)
        limit_down = today_close * (1 - limit_pct)

        if price > limit_up:
            return False, round(limit_up, 2), f"Price exceeds limit up ({limit_pct}%)"
        if price < limit_down:
            return False, round(limit_down, 2), f"Price below limit down ({limit_pct}%)"

        if price < 1.0:
            price = round(price / 0.01) * 0.01

        return True, price, "Valid"

    def load_historical_data(self, data_dir: str):
        """Load historical market data for all stocks."""
        self.load_stock_list(data_dir)

        market_dir = os.path.join(data_dir, 'market')
        if not os.path.exists(market_dir):
            logger.error(f"Market data directory not found: {market_dir}")
            return

        for code in self.stock_list:
            data_file = os.path.join(market_dir, f"{code}_daily_adjusted.csv")
            if os.path.exists(data_file):
                df = pd.read_csv(data_file)
                self.historical_data[code] = df
                logger.info(f"Loaded {code} daily data: {len(df)} records")

    def place_order(self, stock_code: str, direction: str, price: float,
                   quantity: int, date: date) -> Tuple[Optional[Trade], str]:
        """Place and execute a limit order."""
        if not self.is_trading_day(date):
            return None, "Market is closed"

        if stock_code not in self.stock_list:
            return None, f"Stock {stock_code} not in reference list"

        # T+1 rule for sell
        if direction == TradeType.SELL:
            current_shares = self.position.get(stock_code, {}).get('shares', 0)
            t_plus_one = self.t_plus_one_shares.get(stock_code, 0)
            sellable = current_shares - t_plus_one

            if sellable <= 0 and self.position.get(stock_code, {}).get('shares', 0) > 0:
                return None, "T+1 settlement: shares bought today cannot be sold"

            quantity = min(quantity, sellable)
            if quantity <= 0:
                return None, "Insufficient shares"

        # Validate price
        is_valid, adjusted_price, price_reason = self.validate_price(price, date, stock_code)
        if not is_valid:
            return None, f"Price validation failed: {price_reason}"

        trade_amount = price * quantity
        costs = self.calculated_fees.calculate_trade_cost(trade_amount, direction)

        # Check funds for buy
        if direction == TradeType.BUY:
            available = self.cash
            required = trade_amount + costs['total_cost']
            if available < required:
                return None, f"Insufficient funds: need ¥{required:.2f}, have ¥{available:.2f}"

        trade = Trade(
            trade_id=f"t_{len(self.trade_history) + 1:04d}",
            date=date.strftime('%Y-%m-%d'),
            stock_code=stock_code,
            board=self.get_board(stock_code),
            direction=direction,
            price=adjusted_price,
            quantity=quantity,
            trade_amount=trade_amount,
            costs=costs
        )

        if direction == TradeType.BUY:
            self.cash -= costs['total_cost']

            old_shares = self.position.get(stock_code, {}).get('shares', 0)
            if stock_code in self.position:
                avg_price = self.position[stock_code]['avg_price']
                old_cost = old_shares * avg_price
                new_cost = quantity * adjusted_price
                total_shares = old_shares + quantity
                total_cost = old_cost + new_cost
                new_avg_price = total_cost / total_shares
            else:
                avg_price = adjusted_price
                total_shares = quantity
                total_cost = trade_amount
                new_avg_price = avg_price

            self.position[stock_code] = {
                'shares': total_shares,
                'avg_price': round(new_avg_price, 4),
                'cost_basis': total_cost
            }

            self.t_plus_one_shares[stock_code] = quantity
            trade.pnl = -costs['total_cost']
            trade.pnl_rate = trade.pnl / trade_amount if trade_amount > 0 else 0
            self.trade_history.append(trade)

        else:  # SELL
            net_proceeds = costs['total_cost']
            self.cash += net_proceeds
            self.t_plus_one_funds.append(trade_amount)

            if stock_code in self.position:
                current_shares = self.position[stock_code]['shares']
                self.position[stock_code]['shares'] -= quantity
                self.position[stock_code]['cost_basis'] *= ((current_shares - quantity) / current_shares)
                if self.position[stock_code]['shares'] <= 0:
                    del self.position[stock_code]
                    self.t_plus_one_shares[stock_code] = 0

            trade.pnl = trade_amount - costs['total_cost']
            trade.pnl_rate = trade.pnl / trade_amount if trade_amount > 0 else 0
            self.trade_history.append(trade)

        return trade, "TRADE executed"

    def get_portfolio_value(self, date: date = None) -> float:
        """Calculate total portfolio value (cash + stock positions)."""
        if date is None:
            date = self.current_date

        current_prices = {}
        if date in self.historical_data:
            df = self.historical_data[date]
            for _, row in df.iterrows():
                current_prices[str(row['code'])] = row['close']

        stock_value = sum(
            self.position[code]['shares'] * current_prices.get(code, 0)
            for code in self.position
        )

        return round(self.cash + stock_value, 2)

    def set_current_date(self, date_str: str):
        try:
            self.current_date = datetime.strptime(date_str, '%Y-%m-%d').date()
        except ValueError:
            self.current_date = datetime.strptime(date_str, '%Y/%m/%d').date()


class MomentumValueStrategy:
    """Momentum-Value Hybrid Strategy."""

    def __init__(self, params: Dict = None):
        self.params = params or {}
        self.name = self.params.get('name', 'MomentumValueStrategy')
        self.version = self.params.get('version', '1.0')
        self.initial_capital = self.params.get('initial_capital', 1000000)
        self.max_single_position = self.params.get('max_single_position', 0.25)
        self.max_total_position = self.params.get('max_total_position', 0.80)
        self.max_stocks = self.params.get('max_stocks', 8)
        self.max_drawdown = self.params.get('max_drawdown', 0.15)
        self.max_consecutive_losses = self.params.get('max_consecutive_losses', 5)
        self.cool_down_days = self.params.get('cool_down_days', 3)
        self.cooldown_until = {}
        self.current_holdings = {}
        self.current_portfolio_value = self.initial_capital
        self.universe = {}
        self.trade_log = []
        self.current_date = None

    def calculate_momentum_score(self, stock_code: str, lookback_days: int = 20) -> float:
        """Calculate momentum score from -1 to 1."""
        df = self.universe.get(stock_code)
        if df is None or len(df) < lookback_days:
            return 0.0

        closes = df['close'].values[-lookback_days:]
        returns = (closes[1:] / closes[:-1] - 1)
        avg_return = returns.mean() if len(returns) > 0 else 0
        volatility = returns.std() if len(returns) > 1 else 1

        # Score: high return + low volatility = high momentum
        momentum_score = (avg_return * 10) / max(volatility, 0.001)
        return min(max(momentum_score, -1.0), 1.0)

    def calculate_value_score(self, stock_code: str) -> float:
        """Calculate value score from -1 (expensive) to +1 (cheap)."""
        df = self.universe.get(stock_code)
        if df is None or len(df) < 60:
            return 0.0

        closes = df['close'].values
        ma60 = np.mean(closes[-60:])
        current_price = closes[-1]

        price_ratio = current_price / ma60 if ma60 > 0 else 1.0
        value_score = 1.0 - price_ratio  # Lower ratio = better value
        return max(-1.0, min(value_score, 1.0))

    def get_signal(self, stock_code: str, date: date) -> Tuple[float, str]:
        """Get composite signal (buy/sell/neuttral)."""
        momentum = self.calculate_momentum_score(stock_code)
        value = self.calculate_value_score(stock_code)

        # Weighted: 40% momentum, 60% value
        score = 0.4 * momentum + 0.6 * value

        if score > 0.3:
            return 1.0, "Buy"
        elif score < -0.3:
            return -1.0, "Sell"
        else:
            return 0.0, "Neutral"

    def check_limits(self, stock_code: str, portfolio_value: float) -> bool:
        """Check position limits."""
        max_single = self.initial_capital * self.max_single_position
        max_total = self.initial_capital * self.max_total_position
        max_stocks = self.initial_capital * self.max_stocks  # Simplified

        current_total = 0
        for code in self.current_holdings:
            current_total += self.current_holdings[code]

        new_total = current_total + portfolio_value
        if new_total > max_total:
            return False
        if portfolio_value > max_single:
            return False
        if len(self.current_holdings) >= self.max_stocks:
            return False
        return True

    def calculate_quantity(self, stock_code: str, signal: float, portfolio_value: float, current_price: float) -> int:
        """Calculate quantity to trade."""
        if signal <= 0:
            return -1  # Sell or no action

        weight = signal
        position_value = portfolio_value * weight
        quantity = int(position_value / current_price / 100) * 100

        if quantity < 100:
            return 100
        return quantity

    def execute_trades(self, date: date, engine: PaperTradingEngine) -> List[Trade]:
        """Execute trades based on signals."""
        trades = []
        portfolio_value = engine.get_portfolio_value(date)

        for stock_code, (signal, description) in self.universe.items():
            # Check cooldown
            if stock_code in self.cooldown_until:
                if self.cooldown_until[stock_code] > date:
                    continue

            # Get current price
            df = self.universe.get(stock_code)
            if df is None:
                continue

            if date not in df['date'].values:
                dates = df['date'].values
                idx = np.searchsorted(dates, date.strftime('%Y-%m-%d'))
                if idx >= len(dates):
                    continue
                current_price = df['close'].values[idx]
            else:
                current_price = df.loc[df['date'] == date, 'close'].values[0]

            signal, description = self.get_signal(stock_code, date)

            if signal == 0:
                continue

            if signal > 0:  # Buy
                if not self.check_limits(stock_code, portfolio_value):
                    continue

                quantity = self.calculate_quantity(stock_code, signal, portfolio_value, current_price)
                if quantity <= 100:
                    continue

                price = current_price
                engine.place_order(stock_code, TradeType.BUY, price, quantity, date)
                self.current_holdings[stock_code] = quantity
                self.current_portfolio_value += portfolio_value * signal
                trades.append(engine.trade_history[-1])
            else:  # Sell
                if stock_code not in self.current_holdings:
                    continue

                # Sell some or all based on signal
                current_shares = self.current_holdings[stock_code]
                qty_to_sell = int(current_shares * self.partial_exit if abs(signal) < 0.5 else 1.0)
                qty_to_sell = min(qty_to_sell, self.current_holdings[stock_code])
                qty_to_sell = ((qty_to_sell // 100) * 100)
                if qty_to_sell < 100:
                    qty_to_sell = 100

                engine.place_order(stock_code, TradeType.SELL, current_price, qty_to_sell, date)

                self.current_holdings[stock_code] -= qty_to_sell
                if self.current_holdings[stock_code] <= 0:
                    del self.current_holdings[stock_code]
                trades.append(engine.trade_history[-1])

        return trades

    def update(self, date: date):
        """Update strategy for a given date."""
        self.current_date = date

        # Generate signals
        signals = {}
        for code in self.universe:
            signals[code] = self.get_signal(code, date)

        # Execute trades
        trades = self.execute_trades(date)
        self.trade_log.extend(trades)

        # Check risk
        if len(engine.portfolio_value_history) > 1:
            prev_value = engine.portfolio_value_history[-2]
            curr_value = engine.get_portfolio_value(date)
            daily_return = (curr_value - prev_value) / prev_value
            if daily_return < -self.max_drawdown:
                logger.warning(f"Max drawdown exceeded!")
                break

        # Check consecutive losses
        if trades:
            total_pnl = sum(t.pnl for t in trades)
            if engine.get_portfolio_value(date) < engine.initial_capital * 0.9:
                self.consecutive_losses += 1
                if self.consecutive_losses > self.max_consecutive_losses:
                    logger.warning(f"Max consecutive losses!")
                    break
            else:
                self.consecutive_losses = 0

        return trades

    def load_universe(self, engine: PaperTradingEngine):
        """Load investable stocks."""
        cutoff_date = datetime.now() - timedelta(days=60)

        for code in engine.stock_list:
            if code not in engine.historical_data:
                continue

            df = engine.historical_data[code]
            if len(df) == 0:
                continue

            # Check if listed recently
            first_date = df['date'].iloc[0]
            if first_date > cutoff_date:
                continue

            # Exclude ST stocks
            if 'ST' in self.universe.get(code, {}).get('name', '').upper():
                continue

            self.universe[code] = self.universe.get(code, {'name': code})


class BacktestRunner:
    """Backtest runner for paper trading strategy."""

    def __init__(self, initial_capital: float = 1000000.0, data_dir: str = None):
        self.initial_capital = initial_capital
        self.data_dir = data_dir
        self.engine = PaperTradingEngine(initial_capital)
        self.strategy = None
        self.portfolio_value_history = []
        self.cumulative_returns = []
        self.max_value = initial_capital
        self.trading_days = []

    def load_data(self):
        if self.data_dir:
            self.engine.load_historical_data(self.data_dir)
            self.engine.load_market_holidays()

            all_dates = set()
            for df in self.engine.historical_data.values():
                for date in df['date']:
                    all_dates.add(date.strftime('%Y-%m-%d'))

            self.trading_days = sorted([d for d in all_dates if d not in self.engine.market_holidays])
            logger.info(f"Loaded {len(self.trading_days)} trading days")

    def run(self, strategy: MomentumValueStrategy, start_date: str = None, end_date: str = None):
        self.strategy = strategy
        self.engine.initial_capital = strategy.initial_capital
        self.engine.cash = strategy.initial_capital
        self.strategy.initial_capital = strategy.initial_capital
        self.strategy.max_single_position = strategy.max_single_position
        self.strategy.max_total_position = strategy.max_total_position

        strategy.engine = self.engine
        strategy.load_universe(self.engine)

        engine = self.engine

        for date_str in self.trading_days:
            date = datetime.strptime(date_str, '%Y-%m-%d').date()

            if start_date:
                if date < datetime.strptime(start_date, '%Y-%m-%d').date():
                    continue
            if end_date:
                if date > datetime.strptime(end_date, '%Y-%m-%d').date():
                    continue

            engine.current_date = date
            engine.cash = strategy.initial_capital
            engine.position = {}
            engine.t_plus_one_shares = {}

            # Run strategy
            strategy.update(date)

            portfolio_value = engine.get_portfolio_value(date)
            self.portfolio_value_history.append(portfolio_value)

            if len(self.portfolio_value_history) > 1:
                prev = self.portfolio_value_history[-2]
                ret = (portfolio_value - prev) / prev
                self.cumulative_returns.append(ret)

            if portfolio_value > self.max_value:
                self.max_value = portfolio_value

            # Check drawdown
            if self.max_value > 0:
                drawdown = (self.max_value - portfolio_value) / self.max_value
                if drawdown > strategy.max_drawdown:
                    logger.warning(f"Drawdown limit exceeded: {drawdown:.2%}")
                    break

    def get_results(self) -> Dict[str, Any]:
        if not self.portfolio_value_history:
            return {'error': 'No trading days'}

        final_value = self.portfolio_value_history[-1]
        total_return = (final_value / self.initial_capital - 1) * 100

        max_dd = self.max_value
        min_value = min(self.portfolio_value_history)
        max_drawdown = (max_dd - min_value) / max_dd * 100 if max_dd > 0 else 0

        daily_ret = np.array(self.cumulative_returns)
        sharpe = 0.0
        if len(daily_ret) > 0 and np.std(daily_ret) > 0:
            sharpe = (np.mean(daily_ret) / np.std(daily_ret)) * np.sqrt(252)

        wins = sum(1 for r in self.cumulative_returns if r > 0)
        win_rate = wins / len(self.cumulative_returns) if self.cumulative_returns else 0

        trades = self.engine.trade_history
        total_trades = len(trades)
